mapper.select:
select id, code, name, avatar, gender, mobile, email, isdn, id_card, district,
       direct_leader_id, direct_leader_name, department_code, department_name, department_id,
       type, status, password, pwd_time, gmt_created, gmt_updated
from tb_im_user
where gmt_created < #{maxTime}

    and id > #{minId}

order by id
limit #{limit}

mapper.update:
update tb_im_user

    name = case id

            when #{userDto.id} then #{userDto.name}

        else name end,
    mobile = case id

            when #{userDto.id} then #{userDto.mobile}

        else mobile end,
    id_card = case id

            when #{userDto.id} then #{userDto.idCard}

        else id_card end

where id in

    #{userDto.id}
